

# Имена файлов и директорий
KNOWN_NODES_DIR_NAME = "known_nodes/"
NODE_ID_FILE_NAME = "node_id"
SIGN_PRIVATE_FILE_NAME = "sign_private"
LOGS_FILE_NAME = "crypto_layer.log"


# Размер чанка (в байтах) на транспортном уровне
CHUNK_SIZE = 150

# Качество сжатия
COMPRESS_QUALITY = 11


# Обмен ключами/подписями при старте зашифрованной сессии (node id,
# подпись, ECDH-публичный ключ) - сколько ждать ответа собеседника, прежде
# чем считать, что рукопожатие не удалось, вместо зависания навсегда.
HANDSHAKE_TIMEOUT_SECONDS = 60

# Как часто повторно отправлять свою часть рукопожатия, пока ответа нет -
# первый пакет мог уйти до того, как у собеседника был готов приёмник
# (оба клиента стартуют почти одновременно), повтор компенсирует эту гонку.
HANDSHAKE_RESEND_INTERVAL_SECONDS = 5
